const CAR_TYPE_KEYWORDS = ['car', 'sedan', 'suv', 'hatchback', 'crossover', 'mpv', 'pickup'];
const BIKE_TYPE_KEYWORDS = ['bike', 'motorcycle', 'scooter'];
const DEPOSIT_PERCENTAGE = 0.3;

